// BIM 模型配置文件
// 每个模型需要在 BIMface 平台获取 viewToken
// autoLoad: 页面加载后是否自动加载模型
// models: 模型列表，每个模型包含 id/name/token 等属性
export const bimModelConfig = {
  autoLoad: true,
  models: [
    {
      id: '石家庄学院平面模型',
      name: '石家庄学院平面模型',
      token: '514d8a74d31e404e992e23884770919b',
      description: '石家庄学院平面模型',
      position: { x: 0, y: 0, z: 0 },
      visible: true
    },
    {
      id: '办公楼',
      name: '办公楼',
      token: '772e88d75b9243ebad88b8698f543653',
      description: '办公楼模型',
      position: { x: 0, y: 0, z: 0 },
      visible: true
    }
  ],
  // 默认视角参数（eye: 相机位置, target: 目标点, up: 上方向）
  defaultView: {
    eye: [200, 200, 200],
    target: [0, 0, 0],
    up: [0, 1, 0]
  }
}
